body:
{
  "pains": [
    {
      "id": "pain:ride-didnt-record",
      "statement": "I finish the walk or the ride and Strava either stopped halfway, logged the wrong time, or came in a mile short - so the effort I actually did isn't there.",
      "element": "b2c:functional:quality",
      "shape": {
        "surface": "The activity is missing, cut off before the end, drawn as straight lines, or shows a distance that does not match what they did and what the phone next to them recorded.",
        "operational": "They run a second app alongside Strava to have a backup, re-record, enter the activity by hand, move the phone to a backpack to chase satellites, or stop trusting it for anything that matters.",
        "personal": "The ride they travelled for is the one with no data: Joshua made a special trip to the mountains for altitude baseline stats, and that is the session the app dropped. It cannot be redone."
      },
      "workflow": "Recording on the phone or Apple Watch from the start of a weekend walk or a trip away, then at the save screen at the end, where the distance is a mile behind the two apps on a friend's phone or the ride is simply not there; then in the Apple Watch, iPad and phone sync afterwards.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "A trip or a session they travelled for, where the activity cannot be repeated if the recording fails.",
          "cites": ["src:1"]
        },
        {
          "event": "A phone OS or app update, after which recording behaves differently from the week before.",
          "cites": ["src:7"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "The last few times that I have used it, it has either stopped before I have finished my walk, or recorded the wrong time.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "The app stopped working and I missed out on the data I'd been hoping to get.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "getting really annoyed now as my strava wont record my rides properly",
              "cites": ["src:7"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "But for what I use it for, I am not paying.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The only record of an effort they actually made, plus the time spent re-recording it or typing it back in by hand.",
          "fears": "That the app cannot be trusted on the one day it matters, so every planned effort is one they may have to do twice.",
          "dream_outcome": "Press start, put the phone away, and find the whole thing there with the right distance when they stop."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": "feat:track",
      "feature_note": "feat:track is the feature that must not fail. This pain is that feature not delivering rather than a missing one, which is why it damages the paid pitch as much as the free one: one reviewer's companion, a paying subscriber, hit a different recording error on the same trip and cancelled.",
      "cites": ["src:1", "src:7"]
    },
    {
      "id": "pain:pay-and-cant-say-why",
      "statement": "I've been paying for years and I genuinely can't tell you what the subscription gets me that the free version doesn't.",
      "element": "b2c:functional:reduces_cost",
      "shape": {
        "surface": "The renewal charge lands and they cannot name a premium feature they used since the last one; the paid tabs are mostly numbers they can already see for free.",
        "operational": "They set a calendar reminder to cancel before the renewal date, downgrade, or keep paying out of vague loyalty while doing route building and analysis in Garmin Connect.",
        "personal": "They call themselves an idiot for it: they unsubscribe, feel like they are missing out, and resubscribe, paying to quiet the fear of missing something rather than for anything they use."
      },
      "workflow": "At renewal: the charge on the card or the reminder email, then the account page on strava.com where the only offered changes are higher-cost plans, and the mental audit of which paid surface - route builder, extra segment leaderboards, fitness and freshness - they actually opened this year.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "The renewal date itself, which is when the audit happens and when cancellation gets diarised.",
          "cites": ["src:6"]
        },
        {
          "event": "A price rise arriving at renewal, which forces subscribers who had been paying on autopilot to justify the spend.",
          "cites": ["src:11", "src:12"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "The main problem as a paying subscriber is that I have genuinely no idea anymore what I'm paying for.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Nothing! It is an absolute joke, or maybe im not target audience for strava.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "I found very little of use and nothing of 'must have' in the full version",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "I like it cuz I'm an idiot and whenever I unsubscribe I feel like I'm missing something out",
              "cites": ["src:5"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "The route creator is about the only thing that makes it worth it",
              "cites": ["src:5"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "I've set a calendar reminder to check 30 days before renewal and cancel if necessary.",
              "cites": ["src:6"]
            }
          ],
          "costs_them": "Roughly £55 to $99 a year for a bundle they cannot itemise, plus the renewal-week audit itself.",
          "fears": "That they are the mug still paying while the free tier does the same job for the people around them.",
          "dream_outcome": "One thing this month that the subscription did for them and free could not."
        }
      },
      "segments": ["seg:serious", "seg:casual"],
      "feature_ref": null,
      "feature_note": "No single feature answers this. The subscribers who can name anything name route building (feat:plans) and wider segment leaderboards (feat:explore), and the ones who cancel say those are not worth the price. What is missing is a reason to renew, not a feature - which is a positioning and offer problem more than a product one.",
      "cites": ["src:1", "src:5", "src:6"]
    },
    {
      "id": "pain:flag-with-no-recourse",
      "statement": "A real ride of mine got flagged as an e-bike or bad GPS, it's off the leaderboards, and nobody at Strava will look at it.",
      "element": "b2c:emotional:rewards_me",
      "shape": {
        "surface": "The activity carries a flag, drops off segment leaderboards and out of totals, and the appeal sits in a support queue that does not answer.",
        "operational": "They email support and wait weeks, re-check their flagged rides by hand, crop the start or end of an activity to clear it, or accept that the ride does not count.",
        "personal": "Shackleton's flags landed only on the rides where he took a KOM, and only after someone accused him by direct message of trail vandalism. The cost is being quietly branded a cheat by the people he rides near, with no way to answer it."
      },
      "workflow": "On the activity page after upload, where the flag notice sits on the ride and the segment leaderboard no longer shows the effort; then the Strava support contact form, then a week or a month of silence.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Taking a KOM or a high segment place near riders who can flag the activity - the flags arrive straight after, and only on the rides that scored.",
          "cites": ["src:2"]
        },
        {
          "event": "A batch re-classification of old activities, where numerous legitimate rides get flagged at once rather than one at a time.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I've had numerous legitimate activities flagged by Strava - not done in a vehicle, no GPS error and Strava support have refused to unflag these.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "On many of my local rides that include Templeton woods in Dundee I have been flagged for 'bad GPS data'.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Tried that a week ago with no result or acknowledgment. Is it normally a slow process?",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Strava support can be glacially slow, I think my last ticket with them took over a month.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "The standing the effort earned - the KOM, the leaderboard place, the season totals - plus weeks of chasing to get it back.",
          "fears": "That the flag is permanent and public, and that riders in their area now think they cheated.",
          "dream_outcome": "A flag they can clear themselves with the file as evidence, or a human who lifts it the same week."
        }
      },
      "segments": ["seg:serious"],
      "feature_ref": null,
      "feature_note": "Flag review is a trust-and-safety process, not a feature listed in brain/company. The feature the flag takes away from them is feat:explore - segments and leaderboards - so the pain is felt on a paid surface even though nothing in the product resolves it.",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:kom-taken-by-a-motor",
      "statement": "The top of the leaderboard is someone on an e-bike or sat in a car, I flagged it, and nothing happened.",
      "element": "b2c:emotional:badge_value",
      "shape": {
        "surface": "A segment KOM is held by a ride that was not ridden, and the flag they file changes nothing: the time stays up.",
        "operational": "They flag rides every other week, message Strava asking for a category that would separate e-bikes, argue about it on forums, or stop looking at the leaderboard and race their friends instead.",
        "personal": null,
        "personal_note": "The quotes stop at fairness and at the game being spoiled ('No way is that fair', 'That kind of stuff breaks the system'). No source shows what it costs the person - the training week, the standing in the local group - and both threads are older (2017 and 2023). Looked in the two forum threads, the Trustpilot reviews and the flagging threads. Asked in q:pains-personal-rung."
      },
      "workflow": "On a local climb they are working up the leaderboard, at the moment a new top time appears in the segment view with the rider's own e-bike photo attached to the activity; then the flag button on that activity, and the notifications that follow it.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Someone taking the KOM on a segment they are actively chasing.",
          "cites": ["src:4"]
        },
        {
          "event": "A rider leaving the bike computer running on the drive home, which drops a motor-vehicle time onto the segment - frequent enough that some riders flag rides fortnightly.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "However, I found today that some dude just took the KOM. He posted his bike's photo on Strava and it's a eBike.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "Is Strava no longer addressing \"flags\" on activities which are clearly in a car or other motorized vehicle? I've \"flagged\" several rides on segments over the past 6 months and Strava hasn't done anything with them.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "I think Strava is a fun way to compete with the people around me. That kind of stuff breaks the system.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "I get the sense that we're in the \"post-leaderboard\" era of Strava.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_looking",
              "verbatim": "Report it and then message strava the need for an ebike category.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "The point of the segment: months of training measured against a time nobody pedalled.",
          "fears": "That leaderboards are decoration now, and the competition they came for is quietly over.",
          "dream_outcome": "A leaderboard where a flagged motor time comes off and stays off, without them having to police it themselves."
        }
      },
      "segments": ["seg:serious"],
      "feature_ref": "feat:explore",
      "feature_note": "feat:explore is segments, leaderboards and challenges. This pain is that feature's integrity: the buyers' complaint is not that leaderboards are missing but that flagging, the mechanism meant to protect them, does not visibly work.",
      "cites": ["src:3", "src:4"]
    },
    {
      "id": "pain:nobody-answers",
      "statement": "I'm locked out or double-charged, I've emailed three times, and all I get is 'someone will get back to you'.",
      "element": "b2c:functional:avoids_hassles",
      "shape": {
        "surface": "Tickets go unanswered for weeks or months; the replies that do arrive are generic, or ask whether the problem is still happening.",
        "operational": "They email again, open a dispute with PayPal or the bank, delete the app to find the cancel link on the website, or post a public review to get noticed.",
        "personal": "A subscriber since 2020 says it stopped being about the money: 'the issue is no longer about £27.50. It is about poor customer service, scripted responses that failed to answer the questions I was actually asking, repeated requests for escalation being ignored, and then complete silence.'"
      },
      "workflow": "After a billing or access event - a renewal, an upgrade that never activated, a double debit, a student discount applied after the renewal date, a logout that needs an emailed code - in the support email thread and on the strava.com account page, where the offered options are higher-priced plans rather than a way out.",
      "type": "felt",
      "confidence": "high",
      "triggers": [
        {
          "event": "Any billing event: renewal, upgrade, double debit, or a discount applied after the renewal date.",
          "cites": ["src:1"]
        },
        {
          "event": "Being logged out and needing an emailed verification code that does not arrive, or arrives outside the window it is valid for.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Paid to upgrade my Strava account four days ago and it still hasn't activated. I've contacted support three times and only get the same generic \"someone will get back to you\" reply.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I've been locked out of my account for two months, but I'm still paying for it.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Support tickets get answered after a month, and the answer is routinely \"do you still have the same problem? Please let us know. Sorry it's taking so long\".",
              "cites": ["src:1"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "This is clearly deliberate to encourage you to give up and remain subscribing. Not impressed.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Weeks of chasing, a subscription they are paying for and cannot use, and in some cases a bank dispute to get the money back.",
          "fears": "That there is nobody behind the app, so anything that breaks stays broken and the money keeps going out.",
          "dream_outcome": "A reply from a person inside a week that answers the question they actually asked."
        },
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Tried that a week ago with no result or acknowledgment. Is it normally a slow process?",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Strava support can be glacially slow, I think my last ticket with them took over a month.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Can't comment on customer service because I can never figure out how to contact them.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "The rides, flags and account access they cannot get fixed, and the time spent working out where to even ask.",
          "fears": "That a problem with their own history - flags, lost activities, a locked account - simply has no route to a human.",
          "dream_outcome": "An obvious way to reach someone, and an acknowledgment that their ticket exists."
        }
      },
      "segments": ["seg:casual", "seg:serious"],
      "feature_ref": null,
      "feature_note": "Support responsiveness is not a feature in brain/company and no feature kills this. It matters to marketing anyway: it is the pain that turns every other pain permanent, and it is the one reviewers reach for when they explain why they left.",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:club-runs-on-a-spreadsheet",
      "statement": "I'm running a challenge for 70-odd people and Strava's club view won't total what we're actually counting, so it lives in a spreadsheet I update by hand.",
      "element": "b2c:functional:organizes",
      "shape": {
        "surface": "The club leaderboard shows the last week and the top 100, ranks mixed-sport clubs by time rather than distance, and leaves out activity types like hikes and walks - so it does not show the number the challenge is about.",
        "operational": "The organiser copies members' activities into a Google Sheet by hand, using kudos as a tick-off for what they have already logged, or bolts on a Chrome extension, Zapier, or a self-written dashboard on the API.",
        "personal": "The organiser ends up doing a weekly clerical job on top of their own riding, transferring every member's activity into a sheet, and the club never sees that work."
      },
      "workflow": "Setting up a workplace or club challenge inside a Strava club, then weekly: the club leaderboard on the Strava website versus the app (distance on one, time on the other), and a Google Sheet where 70+ members' weekly mileage gets typed in by hand.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Launching a club or workplace challenge with a distance target and more than one activity type.",
          "cites": ["src:8"]
        },
        {
          "event": "A club whose members walk and hike as well as ride, since the default totals exclude those types.",
          "cites": ["src:9"]
        }
      ],
      "who_feels": ["champion"],
      "by_role": {
        "champion": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Strava is a great way to build some momentum. But it only tracks group activity in time, and not distance.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_looking",
              "verbatim": "anyone know of a better way for 70+ people to log their weekly mileage??",
              "cites": ["src:8"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "people logged on Strava and she manually transferred into a spreadsheet giving Kudos when she'd logged it.",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "the default club views were too limited and didn't work for us",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "An hour or two of retyping other people's activities every week, for as long as the challenge runs.",
          "fears": "That momentum dies the week they stop updating the sheet, and the club goes quiet.",
          "dream_outcome": "A club view that totals what the club is counting - every activity type, over the whole challenge, not just last week's top 100."
        }
      },
      "segments": ["seg:clubs"],
      "feature_ref": "feat:explore",
      "feature_note": "feat:explore covers clubs and challenges, so this is the shape of an existing feature rather than its absence: weekly window, top 100, time-based for mixed sport, walks and hikes excluded from totals. Organisers leave the product for a spreadsheet at exactly that edge, and two of them built their own tooling instead.",
      "cites": ["src:8", "src:9"]
    },
    {
      "id": "pain:strangers-know-where-i-ride",
      "statement": "People I've never heard of follow me and kudos every ride, and my activities start at my front door with the bikes in the garage.",
      "element": "b2c:emotional:reduces_anxiety",
      "shape": {
        "surface": "Follow requests and instant kudos from strangers in other countries, some on accounts with a single ride logged, arriving before the activity has even been named.",
        "operational": "They vet or ignore every request, switch the account to approve followers, set privacy zones around the house, or start rides away from home.",
        "personal": "The worry is specific and domestic rather than abstract: that the stranger is working out where the bikes are kept."
      },
      "workflow": "In the Strava notifications tab, where the follow request and the immediate kudos land before the ride is named; and at the start of a ride from home, in the privacy settings that hide the first and last few hundred metres.",
      "type": "felt",
      "confidence": "medium",
      "triggers": [
        {
          "event": "Beating a stranger on a segment, which surfaces you to them and brings the follow request.",
          "cites": ["src:10"]
        },
        {
          "event": "Joining a club challenge, which makes a member's activities visible to a much wider group than their own followers.",
          "cites": ["src:8"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Does anyone else get requests from people they've never heard of to follow you on Strava? I've had 3 or 4, and so has Mr Pea. I don't get why anyone would do that unless they are hoping to find out where we live and pinch our bikes.",
              "cites": ["src:10"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "The really odd requests come from random Australians or Americans. Either way if I don't know them I ignore them.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "Yup, one had only logged a single ride. Bit strange, but I did wonder about that.",
              "cites": ["src:10"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "has become a vehicle for scammers looking to follow me",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Don't forget to set your privacy settings for your start and finish (home or elsewhere) otherwise you may lose your bikes.",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "Vetting every new follower, and a permanent low-level calculation about what their map gives away.",
          "fears": "That the app showing off their best rides is also showing a stranger which garage holds the bikes.",
          "dream_outcome": "Share the ride without publishing where it started, and never have to judge a stranger's profile again."
        }
      },
      "segments": ["seg:serious", "seg:clubs"],
      "feature_ref": null,
      "feature_note": "feat:beacon is live location sharing with people they choose, which answers a different worry - being findable when they want to be. The controls these buyers actually use, privacy zones and follower approval, are not listed as features in brain/company and probably should be.",
      "cites": ["src:1", "src:10"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers discuss Strava against named alternatives without prompting - Garmin Connect and its route builder come up repeatedly in the same threads where people weigh the subscription - so they know solutions exist and are comparing them, not discovering the category.",
      "cites": ["src:5"]
    },
    "seg:casual": {
      "level": "problem",
      "rationale": "The free-tier walker knows exactly what is wrong (recording stops, distance is short, a friend's other two apps agree with each other and not with Strava) and names no alternative at all, only a refusal to pay. That is problem-aware, not solution-aware.",
      "cites": ["src:1"]
    },
    "seg:serious": {
      "level": "most_aware",
      "rationale": "These are current or recent subscribers who know the product and the price and are deciding whether to renew: a thread opens with 'Is it worth it? If so, what parts make it worth it for you?' and pricing threads have people diarising cancellation 30 days before renewal. They need a reason now, not an introduction.",
      "cites": ["src:5", "src:6"]
    },
    "seg:clubs": {
      "level": "solution",
      "rationale": "Club organisers have named the limitation and gone shopping for fixes - a ladder-tracking site, a Chrome extension, a Zapier-to-Sheets chain, a self-built API dashboard - which is the behaviour of people who know solutions exist and have not found the right one.",
      "cites": ["src:8", "src:9"]
    }
  },
  "stats": [
    {
      "id": "stat:uk-monthly-up-28-percent",
      "stat": "Strava's UK monthly subscription went from £6.99 to £8.99 in January 2023, a rise of at least 28%.",
      "scope": "UK monthly plan only, announced January 2023. road.cc reports 'a jump of over 28 per cent' and DC Rainmaker 'about a 29% increase'; the lower figure is used here. Increases varied by country and by renewal date, and DC Rainmaker separately reports some US monthly plans going from $5.99 to $11.99, which only one of the two sources covers and so is not claimed as a number.",
      "cites": ["src:11", "src:12"]
    },
    {
      "id": "stat:uk-annual-up-15-percent",
      "stat": "Over the same change the UK annual plan went from £47.99 to £54.99, about 15%.",
      "scope": "UK annual plan, January 2023. Both sources give the price pair; the percentage is DC Rainmaker's arithmetic ('about a 15% increase'). Useful as the counterpoint: the annual rise was modest, so the reaction in forums was about opacity and about not knowing what the subscription does, not only about the amount.",
      "cites": ["src:11", "src:12"]
    }
  ],
  "keywords": [
    "is strava premium worth it",
    "what do you get with strava subscription",
    "cancel strava subscription",
    "strava alternative",
    "garmin connect vs strava",
    "strava not recording my ride",
    "strava distance wrong",
    "strava stopped recording mid walk",
    "strava activity flagged e-bike",
    "strava flagged bad gps data",
    "how to unflag a strava activity",
    "strava support no response",
    "locked out of strava account still paying",
    "strava kom taken by ebike",
